(7486299, 1191347, 112739, '<td valign="top">I like rainy days. Living where I do, there is only a certain time of year it happens. The focus on the window really works well.</td>', 'I like rainy days. Living where I do, there is only a certain time of year it happens. The focus on the window really works well.', '2016-12-07 21:26:33.000000', NULL, 1),
(7486300, 1190591, 112739, '<td valign="top">Normally don''t like the horizon line exactly in the middle, but this works well due to the interesting sky and clouds.</td>', 'Normally don''t like the horizon line exactly in the middle, but this works well due to the interesting sky and clouds.', '2016-12-07 21:27:53.000000', NULL, 1),
